    const toks = q.split(/[^a-zа-яё0-9]+/).filter((t) => t.length > 2 && t !== 'для');
    const hay = (o) => (o.name + ' ' + o.city + ' ' + o.co + ' ' + o.kind + ' ' + (o.sea ? 'море у моря' : '') + ' ' + (o.st === 'ready' ? 'готов сейчас' : '') + ' ' + o.dev).toLowerCase().replace('апартаменты', 'апартамент квартира').replace('вилла', 'вилла дом');
