    const budLabel = budLabel0 + (S.bby === 'sqm' ? ' за м²' : '');
    const mkP = (id, kind, title, label, active, clear, extra) => Object.assign({ id: id, kind: kind, title: title, label: active ? label : title, on: active, cls: active ? 'is-on' : '', isOpen: S.open === id, expanded: S.open === id, toggle: () => set({ open: S.open === id ? '' : id }), clear: () => up(clear), isLoc: kind === 'loc', isChk: kind === 'chk', isChips: kind === 'chips', isBud: kind === 'bud' }, extra);
